  // Get cashier journal stats
  app.get("/api/cashier-journals/stats/summary", isAuthenticated, requirePermission("cashier_journal", "view"), async (req, res) => {
    // Disable caching to ensure fresh data with filters
    res.set({
      'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
      'Pragma': 'no-cache',
      'Expires': '0',
      'Surrogate-Control': 'no-store'
    });
    
    try {
      const { branchId, status, cashierId, dateFrom, dateTo } = req.query;
      const user = getCurrentUser(req);
      
      // DEBUG: Log query parameters
      console.log("[STATS DEBUG] Query params:", { branchId, status, cashierId, dateFrom, dateTo });
      
      // SECURITY: Use getEffectiveBranchFilter for multi-branch support
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);
      
      // DEBUG: Log branch filter result
      console.log("[STATS DEBUG] Branch filter result:", branchFilter);
      
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      // Get all journals first
      let journals = await storage.getAllCashierJournals();
      
      // Apply same filtering as the main journals endpoint
      if (!isUserAdmin(req)) {
        // Get allowed branches
        const allowedBranches = branchFilter.branchIds || (branchFilter.singleBranchId ? [branchFilter.singleBranchId] : []);
        
        const isManagerUser = await canUserViewAllCashiers(req);
        
        if (isManagerUser) {
          journals = journals.filter(j => allowedBranches.includes(j.branchId));
        } else {
          const userId = String(user.id);
          journals = journals.filter(j => 
            allowedBranches.includes(j.branchId) && String(j.cashierId) === userId
          );
        }
      } else if (branchFilter.singleBranchId) {
        journals = journals.filter(j => j.branchId === branchFilter.singleBranchId);
      }
      
      // DEBUG: Log journals count after branch filter
      console.log("[STATS DEBUG] Journals after branch filter:", journals.length);
      
      // Apply additional filters to match the table view
      if (status && status !== "all") {
        journals = journals.filter(j => j.status === status);
      }
      
      if (cashierId && cashierId !== "all") {
        journals = journals.filter(j => String(j.cashierId) === String(cashierId));
      }
      
      if (dateFrom) {
        journals = journals.filter(j => j.journalDate >= String(dateFrom));
      }
      
      if (dateTo) {
        journals = journals.filter(j => j.journalDate <= String(dateTo));
      }
      
      // Calculate stats from filtered journals using COMPREHENSIVE net variance
      // Net variance = (actualCashDrawer + totalBankTerminalAmount) - (totalSales - returnAmount)
      const totalJournals = journals.length;
      const totalSalesSum = journals.reduce((sum, j) => sum + (j.totalSales || 0), 0);
      
      // Calculate comprehensive net variance for each journal
      const journalsWithNetVariance = journals.map(j => {
        const actualCash = j.actualCashDrawer || 0;
        const terminalTotal = j.totalBankTerminalAmount || 0;
        const netSales = (j.totalSales || 0) - (j.returnAmount || 0);
        const netVariance = (actualCash + terminalTotal) - netSales;
        return { ...j, netVariance };
      });
      
      // Categorize by net variance (comprehensive)
      const netShortages = journalsWithNetVariance.filter(j => j.netVariance < -5); // Allow 5 SAR tolerance
      const netSurpluses = journalsWithNetVariance.filter(j => j.netVariance > 5);
      const shortageAmount = netShortages.reduce((sum, j) => sum + Math.abs(j.netVariance), 0);
      const surplusAmount = netSurpluses.reduce((sum, j) => sum + j.netVariance, 0);
      
      // Calculate average ticket: use customer count if available, otherwise use journal count
      const totalCustomers = journals.reduce((sum, j) => sum + (j.customerCount || 0), 0);
      // If no customer count data, calculate average per journal instead
      const averageTicket = totalCustomers > 0 
        ? totalSalesSum / totalCustomers 
        : (totalJournals > 0 ? totalSalesSum / totalJournals : 0);
      
      res.json({
        totalJournals,
        totalSales: totalSalesSum,
        totalShortages: netShortages.length,
        totalSurpluses: netSurpluses.length,
        shortageAmount,
        surplusAmount,
        averageTicket,
      });
    } catch (error) {
      console.error("Error fetching cashier journal stats:", error);
      res.status(500).json({ error: "Failed to fetch cashier journal stats" });
    }
  });

  // Get all payment breakdowns for journals in a date range (for reports)
  app.get("/api/cashier-payment-breakdowns", isAuthenticated, requirePermission("cashier_journal", "view"), async (req, res) => {
    try {
      const { branchId, startDate, endDate } = req.query;
      
      // SECURITY: Use getEffectiveBranchFilter for multi-branch support
      const queryBranchId = branchId as string | undefined;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId);
      
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }
      
      // Get all journals first with date filter
      let journals = await storage.getAllCashierJournals();
      
      // Apply branch filter
      if (branchFilter.singleBranchId) {
        journals = journals.filter(j => j.branchId === branchFilter.singleBranchId);
      } else if (branchFilter.branchIds) {
        journals = journals.filter(j => branchFilter.branchIds!.includes(j.branchId));
      }
      
      // SECURITY: Non-admin/manager users can only see their own payment breakdowns
      const canViewAllPayments = await canUserViewAllCashiers(req);
      if (!canViewAllPayments) {
        const user = getCurrentUser(req);
        journals = journals.filter(j => String(j.cashierId) === String(user.id));
      }
      
      // Apply date filter
      if (startDate && typeof startDate === 'string') {
        journals = journals.filter(j => j.journalDate && j.journalDate >= startDate);
      }
      if (endDate && typeof endDate === 'string') {
        journals = journals.filter(j => j.journalDate && j.journalDate <= endDate);
      }
      
      // Get payment breakdowns for all matching journals
      const journalIds = journals.map(j => j.id);
      if (journalIds.length === 0) {
        return res.json([]);
      }
      
      // Fetch all payment breakdowns in parallel for better performance
      const breakdownPromises = journalIds.map(async (journalId) => {
        const breakdowns = await storage.getPaymentBreakdowns(journalId);
        const journal = journals.find(j => j.id === journalId);
        return breakdowns.map(b => ({
          ...b,
          branchId: journal?.branchId,
          journalDate: journal?.journalDate,
        }));
      });
      
      const breakdownsArrays = await Promise.all(breakdownPromises);
      const allBreakdowns = breakdownsArrays.flat();
      
      res.json(allBreakdowns);
    } catch (error) {
      console.error("Error fetching payment breakdowns:", error);
      res.status(500).json({ error: "Failed to fetch payment breakdowns" });
    }
  });

