  // Create new batch
  app.post("/api/daily-production/batches", isAuthenticated, requirePermission("production", "create"), async (req, res) => {
    try {
      const user = (req as any).user;
      const { branchId, productId, productName, productCategory, quantity, unit, destination, notes, producedAt, productionDate, status, chefId, chefName, sourceBatchId } = req.body;
      
      // Validate required fields
      if (!branchId || typeof branchId !== 'string') {
        return res.status(400).json({ error: "الفرع مطلوب" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const hasAccess = await canAccessBranch(req, branchId);
        if (!hasAccess) {
          return res.status(403).json({ error: "غير مصرح بإنشاء دفعات لهذا الفرع" });
        }
      }
      if (!productName || typeof productName !== 'string') {
        return res.status(400).json({ error: "اسم المنتج مطلوب" });
      }
      if (quantity === undefined || quantity === null || isNaN(Number(quantity)) || Number(quantity) <= 0) {
        return res.status(400).json({ error: "الكمية يجب أن تكون رقماً صحيحاً أكبر من صفر" });
      }
      if (!destination || typeof destination !== 'string') {
        return res.status(400).json({ error: "الوجهة مطلوبة" });
      }
      
      // Validate destination value
      const validDestinations = ['display_bar', 'kitchen_trolley', 'freezer', 'refrigerator'];
      if (!validDestinations.includes(destination)) {
        return res.status(400).json({ error: "الوجهة غير صالحة" });
      }

      // Validate status value if provided
      const validStatuses = ['finished', 'in_progress'];
      if (status && !validStatuses.includes(status)) {
        return res.status(400).json({ error: "الحالة غير صالحة" });
      }
      
      const batchData = {
        branchId,
        productId: productId ? Number(productId) : null,
        productName: productName.trim(),
        productCategory: productCategory || null,
        quantity: Number(quantity),
        unit: unit || 'قطعة',
        destination,
        notes: notes || null,
        recordedBy: user?.id || null,
        recorderName: user?.firstName ? `${user.firstName} ${user.lastName || ''}`.trim() : user?.username || null,
        producedAt: producedAt ? new Date(producedAt) : new Date(),
        productionDate: productionDate || null, // User's local date YYYY-MM-DD
        status: status || 'finished',
        chefId: chefId || null,
        chefName: chefName || null,
        sourceBatchId: sourceBatchId ? Number(sourceBatchId) : null,
      };
      
      const userName = user?.firstName ? `${user.firstName} ${user.lastName || ''}`.trim() : user?.username || '';
      const result = await storage.createDailyProductionBatchWithTransfer(batchData, user?.id, userName);
      
      res.status(201).json({ ...result.batch, transferred: result.transferred });
    } catch (error) {
      console.error("Error creating batch:", error);
      res.status(500).json({ error: "فشل في إنشاء دفعة الإنتاج" });
    }
  });

  // Update batch
  app.patch("/api/daily-production/batches/:id", isAuthenticated, requirePermission("production", "edit"), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (isNaN(id)) {
        return res.status(400).json({ error: "معرف غير صالح" });
      }
      
      // SECURITY: Verify branch access for non-admin users
      if (!isUserAdmin(req)) {
        const existingBatch = await storage.getDailyProductionBatch(id);
        if (existingBatch?.branchId) {
          const hasAccess = await canAccessBranch(req, existingBatch.branchId);
          if (!hasAccess) {
            return res.status(403).json({ error: "غير مصرح بتعديل هذه الدفعة" });
          }
        }
      }
      
      // Validate allowed update fields
      const allowedFields = ['productName', 'productCategory', 'quantity', 'unit', 'destination', 'notes', 'status', 'chefId', 'chefName'];
      const updateData: any = {};
      
      for (const field of allowedFields) {
        if (req.body[field] !== undefined) {
          if (field === 'quantity') {
            const qty = Number(req.body[field]);
            if (isNaN(qty) || qty <= 0) {
              return res.status(400).json({ error: "الكمية يجب أن تكون رقماً صحيحاً أكبر من صفر" });
            }
            updateData[field] = qty;
          } else if (field === 'destination') {
            const validDestinations = ['display_bar', 'kitchen_trolley', 'freezer', 'refrigerator'];
            if (!validDestinations.includes(req.body[field])) {
              return res.status(400).json({ error: "الوجهة غير صالحة" });
            }
            updateData[field] = req.body[field];
          } else if (field === 'status') {
            const validStatuses = ['finished', 'in_progress'];
            if (!validStatuses.includes(req.body[field])) {
              return res.status(400).json({ error: "الحالة غير صالحة" });
            }
            updateData[field] = req.body[field];
          } else {
            updateData[field] = req.body[field];
          }
        }
      }
      
      const user = (req as any).user;
      const userName = user?.firstName ? `${user.firstName} ${user.lastName || ''}`.trim() : user?.username || '';
      const result = await storage.updateDailyProductionBatchWithTransfer(id, updateData, user?.id, userName);
      
      if (!result.batch) {
        return res.status(404).json({ error: "دفعة الإنتاج غير موجودة" });
      }
      
      res.json({ ...result.batch, transferred: result.transferred });
    } catch (error) {
      console.error("Error updating batch:", error);
      res.status(500).json({ error: "فشل في تحديث دفعة الإنتاج" });
    }
  });

