  // ==========================================
  // Cashier Performance Sales Data API - بيانات مبيعات أداء الكاشير
  // ==========================================

  app.get("/api/cashier-performance-sales", isAuthenticated, requirePermission("cashier_performance", "view"), async (req, res) => {
    try {
      const { branchId, date, shiftType } = req.query;
      
      console.log("[cashier-performance-sales] Request:", { branchId, date, shiftType });
      
      // SECURITY: Apply branch filter
      const branchFilter = getEffectiveBranchFilter(req, branchId as string);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }

      // Get cashier sales journals for the date
      const filters: any = {};
      if (date) {
        filters.startDate = date as string;
        filters.endDate = date as string;
      }
      if (branchFilter.singleBranchId) {
        filters.branchId = branchFilter.singleBranchId;
      } else if (branchId && branchId !== 'all') {
        filters.branchId = branchId as string;
      }

      let journals = await storage.getCashierSalesJournals(filters);
      
      // Filter by shiftType if specified
      if (shiftType && shiftType !== 'all') {
        journals = journals.filter(j => j.shiftType === shiftType);
      }
      
      // Group sales by cashier and shift
      const salesByCashier: Record<string, {
        cashierId: string;
        cashierName: string;
        branchId: string;
        shiftType: string;
        totalSales: number;
        transactionCount: number;
        averageTicket: number;
      }> = {};

      for (const journal of journals) {
        const key = `${journal.cashierId}-${journal.shiftType}`;
        if (!salesByCashier[key]) {
          salesByCashier[key] = {
            cashierId: journal.cashierId || '',
            cashierName: journal.cashierName || '',
            branchId: journal.branchId || '',
            shiftType: journal.shiftType || '',
            totalSales: 0,
            transactionCount: 0,
            averageTicket: 0,
          };
        }
        salesByCashier[key].totalSales += Number(journal.totalSales || 0);
        salesByCashier[key].transactionCount += Number(journal.transactionCount || 0);
      }

      // Calculate average ticket
      for (const key in salesByCashier) {
        const data = salesByCashier[key];
        data.averageTicket = data.transactionCount > 0 
          ? Math.round((data.totalSales / data.transactionCount) * 100) / 100 
          : 0;
      }

      let result = Object.values(salesByCashier);
      
      // SECURITY: Non-admin/manager cashiers can only view their own sales
      const canViewAll = await canUserViewAllCashiers(req);
      if (!canViewAll) {
        const user = getCurrentUser(req);
        result = result.filter(r => String(r.cashierId) === String(user.id));
      }
      
      console.log("[cashier-performance-sales] Result:", result.length, "records");
      res.json(result);
    } catch (error) {
      console.error("Error fetching cashier performance sales:", error);
      res.status(500).json({ error: "فشل في جلب بيانات المبيعات" });
    }
  });

  // API for detailed cashier journals report with date range
  // Security: Non-admin/manager users can only see their own journals
  app.get("/api/cashier-journals-report", isAuthenticated, requirePermission("cashier_performance", "view"), async (req, res) => {
    try {
      const user = (req as any).currentUser as User;
      if (!user) {
        return res.status(401).json({ error: "غير مسجل الدخول" });
      }
      const { branchId, startDate, endDate, cashierId } = req.query;
      
      const branchFilter = getEffectiveBranchFilter(req, branchId as string);
      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }

      // Security check: Determine if user can view all cashiers or only their own
      const canViewAllCashiersFlag = await canUserViewAllCashiers(req);
      
      console.log("[cashier-journals-report] User:", user.id, "Role:", user.role, "CanViewAll:", canViewAllCashiersFlag);

      const filters: any = {};
      if (startDate) filters.startDate = startDate as string;
      if (endDate) filters.endDate = endDate as string;
      if (branchFilter.singleBranchId) {
        filters.branchId = branchFilter.singleBranchId;
      } else if (branchId && branchId !== 'all') {
        filters.branchId = branchId as string;
      }

      let journals = await storage.getCashierSalesJournals(filters);
      
      // Get user and branch names
      const users = await storage.getAllUsers();
      const branches = await storage.getAllBranches();
      const userMap = new Map(users.map(u => [u.id, `${u.firstName || ''} ${u.lastName || ''}`]));
      const branchMap = new Map(branches.map(b => [b.id, b.name]));

      // For non-admin cashiers: calculate their real contribution % from ALL branch data before filtering
      let myContributionPercent: number | null = null;
      if (!canViewAllCashiersFlag) {
        const allBranchTotal = journals.reduce((sum, j) => sum + (Number(j.totalSales) || 0), 0);
        const myTotal = journals
          .filter(j => String(j.cashierId) === String(user.id))
          .reduce((sum, j) => sum + (Number(j.totalSales) || 0), 0);
        myContributionPercent = allBranchTotal > 0 ? (myTotal / allBranchTotal) * 100 : 0;
        console.log("[cashier-journals-report] Restricting to user's own journals. Contribution:", myContributionPercent?.toFixed(1), "%");
        journals = journals.filter(j => String(j.cashierId) === String(user.id));
      } else if (cashierId && cashierId !== 'all') {
        journals = journals.filter(j => j.cashierId === cashierId);
      }

      const result = journals.map(j => ({
        id: j.id,
        cashierId: j.cashierId,
        cashierName: userMap.get(j.cashierId || '') || 'غير معروف',
        branchId: j.branchId,
        branchName: branchMap.get(j.branchId || '') || 'غير معروف',
        date: j.journalDate,
        shiftType: j.shiftType,
        totalSales: Number(j.totalSales) || 0,
        cashSales: Number(j.cashSales) || 0,
        cardSales: Number(j.cardSales) || 0,
        transactionCount: j.transactionCount || 0,
        averageTicket: j.transactionCount ? (Number(j.totalSales) / j.transactionCount) : 0,
      }));

      console.log("[cashier-journals-report] Returning:", result.length, "records");
      res.json({
        journals: result,
        myContributionPercent,
      });
    } catch (error) {
      console.error("Error fetching cashier journals report:", error);
      res.status(500).json({ error: "فشل في جلب تقرير اليوميات" });
    }
  });

