  // ==========================================

  app.get("/api/performance-alerts", isAuthenticated, requirePermission("cashier_performance", "view"), async (req, res) => {
    try {
      const { branchId, date, isRead } = req.query;
      const filters: any = {};
      if (branchId) filters.branchId = branchId;
      if (date) filters.date = date;
      if (isRead !== undefined) filters.isRead = isRead === 'true';
      
      let alerts = await storage.getAllPerformanceAlerts(filters);
      
      // SECURITY: Apply branch filter
      const { branchId: queryBranchId } = req.query;
      const branchFilter = getEffectiveBranchFilter(req, queryBranchId as string | undefined);

      if (!branchFilter.hasAccess) {
        return res.status(403).json({ error: "غير مصرح بالوصول" });
      }

      if (branchFilter.branchIds) {
        alerts = alerts.filter(a => branchFilter.branchIds!.includes(a.branchId || ''));
      }

      // SECURITY: Non-admin/manager users can only see their own alerts
      const canViewAllAlerts = await canUserViewAllCashiers(req);
      if (!canViewAllAlerts) {
        const user = getCurrentUser(req);
        alerts = alerts.filter(a => String(a.cashierId) === String(user.id));
      }

      res.json(alerts);
    } catch (error) {
      console.error("Error fetching performance alerts:", error);
      res.status(500).json({ error: "فشل في جلب التنبيهات" });
    }
  });

