      if (!report) {
        return res.status(404).json({ error: "التقرير غير موجود" });
      }
      
      if (report.status === 'finalized') {
        return res.status(400).json({ error: "لا يمكن حذف تقرير مكتمل" });
      }
      
      await storage.deleteTimesheetReport(id);
      res.status(204).send();
